import { useMemo, useState } from "react";
import { Button, Card, FieldFrame, PageHeader, RecordList, Select, Typography } from "@autograph/components";
import { RecordDetailPanel, RecordListDetailLayout } from "@autograph/compositions";
type Severity="critical"|"warning";type Product={id:string;sku:string;name:string;location:string;locationLabel:string;severity:Severity;onHand:number;reserved:number;reorderPoint:number;daysCover:number;supplier:string;leadTime:string;pack:number;lastReceipt:string;contact:string;terms:string};
const products:Product[]=[{id:"atlas",sku:"HW-1048",name:"Atlas nitrile gloves — M",location:"oakland",locationLabel:"Oakland DC",severity:"critical",onHand:18,reserved:12,reorderPoint:72,daysCover:1.4,supplier:"Northstar Medical Supply",leadTime:"4 business days",pack:24,lastReceipt:"96 units on 14 Aug",contact:"orders@northstarmed.example",terms:"Net 30 · minimum 4 cases"},{id:"beacon",sku:"CL-2201",name:"Beacon surface disinfectant",location:"oakland",locationLabel:"Oakland DC",severity:"warning",onHand:34,reserved:6,reorderPoint:60,daysCover:3.8,supplier:"Clearwell Distribution",leadTime:"6 business days",pack:12,lastReceipt:"60 units on 11 Aug",contact:"supply@clearwell.example",terms:"Net 30 · no minimum"},{id:"cedar",sku:"PK-0912",name:"Cedar specimen bags",location:"reno",locationLabel:"Reno Clinic",severity:"critical",onHand:9,reserved:3,reorderPoint:48,daysCover:1.1,supplier:"Northstar Medical Supply",leadTime:"3 business days",pack:50,lastReceipt:"100 units on 2 Aug",contact:"orders@northstarmed.example",terms:"Net 30 · minimum 2 cases"},{id:"delta",sku:"PP-3140",name:"Delta isolation gowns",location:"reno",locationLabel:"Reno Clinic",severity:"warning",onHand:27,reserved:5,reorderPoint:45,daysCover:4.2,supplier:"Westline Clinical",leadTime:"8 business days",pack:20,lastReceipt:"80 units on 8 Aug",contact:"service@westline.example",terms:"Net 45 · minimum 3 cases"}];
export default function StockExceptions(){const[location,setLocation]=useState("all");const[severity,setSeverity]=useState("all");const[selectedId,setSelectedId]=useState("atlas");const[stage,setStage]=useState<"ready"|"confirm"|"done">("ready");const filtered=useMemo(()=>products.filter(p=>(location==="all"||p.location===location)&&(severity==="all"||p.severity===severity)),[location,severity]);const selected=filtered.find(p=>p.id===selectedId);const changeFilters=(nextLocation:string,nextSeverity:string)=>{const next=products.filter(p=>(nextLocation==="all"||p.location===nextLocation)&&(nextSeverity==="all"||p.severity===nextSeverity));setSelectedId(current=>next.some(p=>p.id===current)?current:(next[0]?.id??""));setStage("ready")};const resetFilters=()=>{setLocation("all");setSeverity("all");setSelectedId("atlas");setStage("ready")};const shortfall=selected?Math.max(0,selected.reorderPoint-selected.onHand):0;const quantity=selected?Math.ceil(shortfall/selected.pack)*selected.pack:0;const projected=selected?selected.onHand+quantity:0;
const filters=<section aria-label="Exception filters" className="grid grid-cols-1 gap-[var(--space-3)] rounded-[var(--radius-panel)] border border-[var(--color-border-subtle)] bg-[var(--color-bg-surface)] p-[var(--space-3)] sm:grid-cols-2"><FieldFrame label="Location" className="min-w-0 w-full"><Select size="sm" value={location} options={[{value:"all",label:"All locations"},{value:"oakland",label:"Oakland DC"},{value:"reno",label:"Reno Clinic"},{value:"none",label:"Portland Hub (0)"}]} onValueChange={v=>{setLocation(v);changeFilters(v,severity)}}/></FieldFrame><FieldFrame label="Severity" className="min-w-0 w-full"><Select size="sm" value={severity} options={[{value:"all",label:"All severities"},{value:"critical",label:"Critical"},{value:"warning",label:"Low"}]} onValueChange={v=>{setSeverity(v);changeFilters(location,v)}}/></FieldFrame></section>;
const resultItems=selected?[{type:"field" as const,id:"modeled",label:"Modeled replenishment quantity",value:`${quantity} units (${quantity/selected.pack} cases)`},{type:"field" as const,id:"projected",label:"Projected on-hand",value:`${projected} units`},{type:"field" as const,id:"shortfall",label:"Shortfall before replenishment",value:`${shortfall} units`},{type:"field" as const,id:"pack",label:"Case pack",value:`${selected.pack} units`},{type:"note" as const,id:"assumption",title:"Model assumption",body:`This simple fixture targets gross on-hand; ${selected.reserved} reserved units are context and are not subtracted.`,tone:"neutral" as const},{type:"note" as const,id:"no-order",title:"Simulation only",body:"No order was placed and underlying stock is unchanged.",tone:"info" as const}]:[];
const stockSection=selected?{id:"stock",title:"Stock evidence",collapsible:stage==="done",defaultOpen:stage!=="done",items:[{type:"field" as const,id:"onHand",label:"On hand",value:`${selected.onHand} units`},{type:"field" as const,id:"reserved",label:"Reserved",value:`${selected.reserved} units`},{type:"field" as const,id:"reorder",label:"Reorder point",value:`${selected.reorderPoint} units`},{type:"field" as const,id:"cover",label:"Days of cover",value:`${selected.daysCover} days`},{type:"field" as const,id:"supplier",label:"Supplier",value:selected.supplier},{type:"field" as const,id:"lead",label:"Lead time",value:selected.leadTime}]}:null;const supplierSection=selected?{id:"supplier-secondary",title:"Secondary supplier facts",defaultOpen:false,items:[{type:"field" as const,id:"supplier-pack",label:"Case pack",value:`${selected.pack} units`},{type:"field" as const,id:"receipt",label:"Last receipt",value:selected.lastReceipt},{type:"field" as const,id:"contact",label:"Order contact",value:selected.contact},{type:"field" as const,id:"terms",label:"Terms",value:selected.terms}]}:null;
const recordList=<RecordList ariaLabel="Low-stock products" heading="Exceptions" summary={`${filtered.length} matching · ${products.length} total`} selectedId={selectedId} onSelect={id=>{setSelectedId(id);setStage("ready")}} items={filtered.map(p=>({id:p.id,primary:p.name,secondary:<Typography as="span" variant="body">{p.sku} · {p.locationLabel}</Typography>,trailing:<><Typography as="span" variant="body-strong">{p.severity==="critical"?"Critical":"Low"}</Typography><Typography as="span" variant="body-strong">{p.daysCover} days cover</Typography></>}))}/>;const list=<div className="grid gap-[var(--space-3)]">{filters}{recordList}</div>;
const detail=selected?<RecordDetailPanel className="h-[min(720px,calc(100vh-12rem))]" labelEmphasis="primary" title={selected.name} subtitle={`${selected.sku} · ${selected.locationLabel}`} status={{label:selected.severity==="critical"?"Critical":"Low",tone:selected.severity==="critical"?"danger":"warning"}} sections={stage==="confirm"?[{id:"confirm",title:`Confirm ${quantity}-unit modeled replenishment`,collapsible:false,items:resultItems}]:stage==="done"?[{id:"mock-result",title:`Modeled replenishment: ${quantity} units · ${projected} projected on-hand`,collapsible:false,items:resultItems},stockSection!,supplierSection!]:[stockSection!,supplierSection!]} actions={stage==="ready"?[{id:"try",label:"Try mock replenishment",intent:"primary"}]:stage==="confirm"?[{id:"cancel",label:"Cancel"},{id:"confirm",label:"Confirm mock",intent:"primary"}]:[{id:"reset",label:"Reset mock"}]} onAction={id=>{if(id==="try")setStage("confirm");if(id==="cancel"||id==="reset")setStage("ready");if(id==="confirm")setStage("done")}}/>:null;
return <main className="min-h-screen bg-[var(--color-bg-page)] px-[var(--space-6)] py-[var(--space-6)]"><div className="mx-auto w-full max-w-[1440px]"><PageHeader title="Stock exceptions" subtitle="Review low-stock evidence and model a replenishment without changing inventory."/><div className="mx-auto mt-[var(--space-5)] w-full max-w-[1240px]">{filtered.length===0?<div className="grid gap-[var(--space-3)]">{filters}<Card><div className="px-[var(--space-6)] py-[var(--space-8)]"><Typography variant="section-title">No exceptions match these filters</Typography><Typography variant="body" tone="muted" className="mt-[var(--space-2)]">Change location or severity, or reset both filters to return to the full exception list.</Typography><Button size="sm" className="mt-[var(--space-4)]" onClick={resetFilters}>Reset filters</Button></div></Card></div>:<RecordListDetailLayout list={list} detail={detail} hasSelection={Boolean(selected)} selectedId={selectedId||undefined} onBack={()=>setSelectedId("")} backLabel="Back to exceptions"/>}</div></div></main>}
